func resident_view(resident_id: String = "") -> Dictionary:
	if not active_ids().has(resident_id):
		return {}
	var person := resident(resident_id)
	var own_events: Array = []
	for event in _state.life.events:
		if event.get("recipient_ids", []).has(resident_id):
			own_events.append(event.duplicate(true))
	return {"identity": {"id": resident_id, "name": resident_name(resident_id), "role": person.role},
		"needs": person.needs.duplicate(true), "inventory": account(resident_id).duplicate(true),
		"experiences": own_events, "observations": _state.godot.observations[resident_id].duplicate(true),
		"available_actions": available(resident_id), "pending": _state.godot.pending.get(resident_id, {}).duplicate(true),
		"nearby_residents": nearby(resident_id), "work": work_view(resident_id)}

func work_view(id: String) -> Dictionary:
	if not active_ids().has(id) or not _has_repair_state():
		return {}
	var own_items: Array = []
	for value in _state.life.items:
		if value.get("owner_id") == id or value.get("custodian_id") == id:
			own_items.append(value.duplicate(true))
	var own_skills: Array = []
	for value in _state.life.skills:
		if value.get("resident_id") == id:
			own_skills.append(value.duplicate(true))
	var own_contracts: Array = []
	for value in _state.life.contracts:
		if value.get("owner_id") == id or value.get("worker_id") == id:
			own_contracts.append(value.duplicate(true))
	return {"materials": work_account(id).duplicate(true), "items": own_items,
		"skills": own_skills, "contracts": own_contracts}

var request_id := "turn:%s:%d:%d" % [id, epoch, number]
var view: Dictionary = town.resident_view(id)
view.world_id = town._state.world_id
# Legacy 'hunger' is actually fullness (food increases it). Normalize the
# model-facing sensor without renaming or rewriting the canonical old field.
if view.needs.has("hunger"):
	view.needs.satiety = view.needs.hunger
	view.needs.erase("hunger")
	view.needs.scale_explanation = "satiety measures fullness: 0 means an empty stomach and 100 means full. Higher energy means more stamina."
view.needs.energy = view.inventory.get("energy", 0)
view.memory = {"previous_decisions": _feedback_history(id, previous).slice(-6)}
for key in ["story", "personality", "faction"]:
	if town.resident(id).has(key):

	request_rules.decision_format["action_groups"] = "Each group has one template and choices mapping action IDs to arguments. Replace {0}, {1}, etc. with that choice's arguments to read its full description; choose the listed action ID."
view["known_rules"] = request_rules
# Context is bounded; canonical full history remains in the world save.
view.experiences = view.get("experiences", []).slice(-16)
view = town.English.project(view)
var seen := _own_seq(id)
var recovery_class := _cold_recovery_class(id, previous)
var recovering := not recovery_class.is_empty()

Require(latest.Metadata.TryGetValue("game.input_id", out var operation) && Guid.TryParse(operation, out _));
Require(latest.Metadata.TryGetValue("game.actor_id", out var actor) && actor.Length is > 0 and <= 128);
using var input = JsonDocument.Parse(latest.Content.OfType<JsonContent>().First().Json);
var root = input.RootElement;
var payload = root.TryGetProperty("payload", out var p) ? p : root.GetProperty("Payload");
var view = payload.GetProperty("resident_view");
// Explicit projection prevents incidental host fields from being sent.
var personal = new Dictionary<string, JsonElement>();
foreach (var key in new[] { "identity", "observations", "needs", "experiences", "memory", "inventory", "actions", "available_actions",
    "nearby_residents", "items", "skills", "contracts", "life_account", "wallet", "nearby_skilled_roles", "action_details", "action_groups", "shared_plans", "known_rules", "unavailable_actions",
    "baking_points" })
    if (view.TryGetProperty(key, out var value)) personal[key] = value;
Require(personal.ContainsKey("identity") && personal.ContainsKey("available_actions"));
Require(S(personal["identity"], "id") == actor);
// These are the town's recipient-filtered historical projections, never
// the world event log, another resident's view, or the GM installation state.
// Keep the latest bounded records independently of the 16 recent events.
ProjectKnowledge(view, personal, "known_skill_notices", 16,
    "actor_id", "skill_id", "source_event_id", "seq", "source", "provenance", "text");
ProjectKnowledge(view, personal, "known_skill_referrals", 16,
    "referrer_id", "referred_resident_id", "skill_id", "referral_event_id", "seq", "source_event_id", "source_seq", "provenance", "text");
