func ready_resident() -> String:
	# A closed episode admits no NEW resident decision, whatever the clock says.
	if _admission_closed:
		return ""
	if inflight.size() >= max_parallel:
		return ""
	var residents: Array = town.active_ids()
	for offset in residents.size():
		var id: String = residents[(_next_resident_index + offset) % residents.size()]
		var record := _record(id)
		if not brains.has(id) or inflight.has(id) or _requires_review(record, id) or _replan_cooling(record):
			continue
		# A pending job normally excludes the resident. A reported blocked material
		# travel episode is the explicit exception: the resident observes the
		# failure and may choose to continue waiting or to cancel that one trip.
		if not town.pending_job(id).is_empty() and town.blocked_material_episode(id).is_empty():
			continue
		# A cold-recovery class is itself the one bounded reason to become due. These
		# receipts have no next_due and may have produced no event, so applying only
		# the ordinary evidence/time gate would admit recovery above but never select it.
		if _cold_recoverable(id, record) or record.is_empty() or _own_seq(id) > int(record.get("seen_seq", 0)) or town._state.godot.elapsed_seconds >= float(record.get("next_due", INF)) or _new_self_repair_offer_due(id, record) or _new_trade_collection_offer_due(id, record) or _terminal_basic_failure_due(id, record) or _terminal_material_depletion_due(id, record):
			return id
	return ""

		var spots: Dictionary = _state.godot.get("foraging_work_spots", {}).get("positions", {})
		return _vector(spots[id]) if spots.has(id) else berry_center()
	return _vector(_state.godot.homes[id])

func host_move(id: String, position_value: Vector3) -> void:
	# Host scene passes the collision-resolved body position; never exposed to a model.
	if active_ids().has(id) and position_value.is_finite():
		_state.godot.positions[id] = [position_value.x, position_value.y, position_value.z]

func available(id: String) -> Array:
	var result: Array = ["wait"]
	if not active_ids().has(id) or _state.godot.pending.has(id):
		return result
	var a := account(id)
	if a.food >= 1 and resident(id).needs.hunger <= 80:
		result.append("eat_ration")
	if a.energy <= 70:
		result.append("rest")
	# The public source's rules are known; current stock is checked on arrival.
	if a.food < 2:
		result.append("harvest_ration")
	return result

func choose_local(id: String) -> String:
